using namespace moon;
Document fixture(){Document d(4,2);d.fillSelectionOrCanvas(0xffffffff);d.addFrame(true);auto s=d.timeline().state();timeline::Group g;g.id="g";g.name=U"G";s.groups.push_back(g);s.layers[0].groupId=g.id;
 timeline::MaskSlot root;root.ownerId=s.layers[0].id;root.frameId=s.frames[0].id;root.mask.id="root";root.mask.moveWithOwner=false;root.mask.surface={};auto& r=root.mask.surface;r.width=3;r.height=2;r.offsetX=-1;r.storageOriginX=8;r.storageOriginY=-4;r.pixels={0xff000000,0,0xff808080,0xff404040,0xffffffff,0xff000000};
 auto linked=root;linked.frameId=s.frames[1].id;linked.mask.id="linked";linked.mask.linkedMaskId="root";linked.mask.visible=false;linked.mask.locked=true;linked.mask.surface.offsetX=3;
 auto group=root;group.ownerId="g";group.group=true;group.mask.id="group";group.mask.surface.offsetX=2;auto groupLink=group;groupLink.frameId=s.frames[1].id;groupLink.mask.id="group-linked";groupLink.mask.linkedMaskId="group";s.masks={root,linked,group,groupLink};const auto archive=project::encodeEditableProject(d);return Document::fromImported(4,2,std::move(s),d.palette(),archive.projectId,U"Mask resize",archive.bytes);}
void sameMasks(const std::vector<timeline::MaskSlot>& a,const std::vector<timeline::MaskSlot>& b,bool persisted=false){CHECK(a.size()==b.size());for(std::size_t i=0;i<a.size();++i){const auto& x=a[i];const auto& y=b[i];CHECK(x.ownerId==y.ownerId&&x.frameId==y.frameId&&x.group==y.group&&x.mask.id==y.mask.id&&x.mask.linkedMaskId==y.mask.linkedMaskId&&x.mask.locked==y.mask.locked&&(persisted||(x.mask.visible==y.mask.visible&&x.mask.moveWithOwner==y.mask.moveWithOwner)));const auto& s=x.mask.surface;const auto& t=y.mask.surface;CHECK(s.width==t.width&&s.height==t.height&&s.offsetX==t.offsetX&&s.offsetY==t.offsetY&&s.pixels==t.pixels);}}
void roundtrip(Document& d,const std::filesystem::path& path){const auto before=d.timeline().state().masks;project::saveDocumentAtomic(d,path);std::ifstream in(path,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto loaded=project::prepareEditableImport(project::readProjectManifest(bytes));CHECK(loaded.width==d.width()&&loaded.height==d.height());sameMasks(before,loaded.timeline.masks,true);for(const auto& slot:loaded.timeline.masks)CHECK(slot.mask.visible&&slot.mask.moveWithOwner);}
int main(int argc,char** argv){try{const auto directory=argc>1?std::filesystem::path(argv[1]):std::filesystem::path("build/mask-resize-owned");std::filesystem::create_directories(directory);
 auto d=fixture();const auto original=d.timeline().state().masks;const auto layer=d.layer().id,first=d.timeline().state().frames[0].id;CHECK(d.selectAttachedMask(layer,first));const auto active=d.activeMaskId();const auto h=d.historyPosition();CHECK(d.resizeCanvas(7,5,CanvasAnchor::Center));CHECK(d.historyPosition()==h+1&&d.activeMaskId()==active);for(std::size_t i=0;i<original.size();++i){const auto& s=d.timeline().state().masks[i].mask.surface;CHECK(s.offsetX==original[i].mask.surface.offsetX+1&&s.offsetY==1&&s.pixels==original[i].mask.surface.pixels);}CHECK(timeline::resolvedMask(d.timeline().state(),layer,d.timeline().state().frames[1].id)->surface.offsetX==0);d.undo();sameMasks(original,d.timeline().state().masks);d.redo();roundtrip(d,directory/"expanded.moonsprite");
 d.undo();CHECK(d.resizeCanvas(2,1,CanvasAnchor::NorthWest,0,0,true));const auto& cropped=d.timeline().state().masks;CHECK(cropped[0].mask.surface.width==2&&cropped[0].mask.surface.pixels==std::vector<Pixel>({0,0xff808080})&&cropped[0].mask.surface.storageOriginX==9);CHECK(cropped[1].mask.surface.width==1&&cropped[1].mask.surface.pixels[0]==0&&cropped[1].mask.linkedMaskId=="root");CHECK(cropped[2].mask.surface.width==1&&cropped[2].mask.surface.pixels[0]==0);d.undo();sameMasks(original,d.timeline().state().masks);d.redo();roundtrip(d,directory/"cropped.moonsprite");
 d.undo();d.previewSelection(SelectionMask{1,0,2,1,{}});CHECK(d.cropCanvas());CHECK(d.width()==2&&d.timeline().state().masks[0].mask.surface.pixels==std::vector<Pixel>{0xff808080});d.undo();sameMasks(original,d.timeline().state().masks);
 CHECK(d.resizeImage(6,3,ImageInterpolation::Nearest));const auto resized=d.timeline().state().masks;CHECK(resized[0].mask.surface.offsetX==-2&&resized[0].mask.surface.width==5&&resized[0].mask.surface.height==3&&resized[0].mask.surface.storageOriginX==0);CHECK(resized[0].mask.surface.pixels[0]==0xff000000&&resized[0].mask.surface.pixels[1]==0xff000000&&resized[0].mask.surface.pixels[2]==0&&resized[0].mask.surface.pixels[3]==0xff808080);CHECK(resized[1].mask.linkedMaskId=="root"&&resized[2].mask.surface.offsetX==3);d.undo();sameMasks(original,d.timeline().state().masks);d.redo();roundtrip(d,directory/"scaled.moonsprite");
 d.undo();CHECK(d.resizeCanvas(3,1,CanvasAnchor::NorthWest,1,0,true));CHECK(d.resizeImage(6,2,ImageInterpolation::Smooth));d.undo();CHECK(d.width()==3);d.undo();sameMasks(original,d.timeline().state().masks);
 timeline::Surface sample;sample.width=2;sample.height=1;sample.pixels={0xff000000,0};const auto normalized=imageResizedSurface(sample,planImageResizeSurface(sample,2,1,3,1),ImageInterpolation::Smooth,true);CHECK(normalized.pixels==std::vector<Pixel>({0xff000000,0xff7f7f7f,0}));
 const auto revision=d.revision(),history=d.historyPosition();bool rejected=false;try{d.resizeCanvas(2,1,CanvasAnchor::Center,std::numeric_limits<int>::max(),0);}catch(const std::length_error&){rejected=true;}CHECK(rejected&&d.revision()==revision&&d.historyPosition()==history);sameMasks(original,d.timeline().state().masks);CHECK(!d.resizeImage(4,2)&&d.historyPosition()==history);
 std::cout<<"Attached mask image/canvas resize and crop checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
